art_7a64fb2b-c800-48b4-a24c-41cea4ab733a_synthtest_MT-1_20260713220713392364	7a64fb2b-c800-48b4-a24c-41cea4ab733a	test-synth	Synthesized test file: .agentic_tests/test_MT_1.test.js\nExecution status: rejected (trivial-guard)\nRole in verdict: excluded — trivial-guard rejected (did not gate; Track A decided)\nTrivial-guard: REJECTED — no expect()/assert() calls found\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\n\nimport { newGame, step } from '../src/game.js';\n\nfunction state(overrides) {\n  return {\n    snake: [\n      { x: 10, y: 10 },\n      { x: 9, y: 10 },\n      { x: 8, y: 10 },\n    ],\n    direction: 'right',\n    food: { x: 15, y: 15 },\n    gameOver: false,\n    score: 0,\n    ...overrides,\n  };\n}\n\ndescribe('score field and scoring logic', () => {\n  test('newGame() returns a state object with score equal to 0', () => {\n    const game = newGame(() => 0);\n    assert.equal(game.score, 0);\n  });\n\n  test('step() on a state about to eat food increases score by 10 times the snake new (post-grow) length, added to prior score', () => {\n    // Snake has length 3, head at (10,10) moving right, food directly ahead.\n    // After eating, snake grows to length 4, so score = 0 + 10*4 = 40.\n    const eating = state({ food: { x: 11, y: 10 }, score: 0 });\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, 4);\n    assert.equal(next.score, 40);\n  });\n\n  test('step() on a state that does not eat food leaves score unchanged from the input state score', () => {\n    const notEating = state({ food: { x: 15, y: 15 }, score: 40 });\n    const next = step(notEating);\n    assert.equal(next.score, 40);\n  });\n\n  test('step() on a game-over state returns the exact same state object unmodified (no score field injected if absent)', () => {\n    const over = {\n      snake: [\n        { x: 10, y: 10 },\n        { x: 9, y: 10 },\n        { x: 8, y: 10 },\n      ],\n      direction: 'right',\n      food: { x: 15, y: 15 },\n      gameOver: true,\n      // score intentionally absent\n    };\n    const next = step(over);\n    assert.deepEqual(next, over);\n    assert.equal('score' in next, false);\n  });\n\n  test('full first-food scenario: snake grows from length 3 to length 4 by eating, resulting score is 40', () => {\n    const eating = state({ food: { x: 11, y: 10 }, score: 0 });\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, 4);\n    assert.equal(next.score, 40);\n  });\n\n  test('second consecutive food-eating scenario starting from score 40 and snake growing from length 4 to length 5 results in score 90', () => {\n    const snakeLen4 = [\n      { x: 11, y: 10 },\n      { x: 10, y: 10 },\n      { x: 9, y: 10 },\n      { x: 8, y: 10 },\n    ];\n    const eatingAgain = state({\n      snake: snakeLen4,\n      food: { x: 12, y: 10 },\n      score: 40,\n    });\n    const next = step(eatingAgain, () => 0);\n    assert.equal(next.snake.length, 5);\n    assert.equal(next.score, 90);\n  });\n});\n	\N	2026-07-13 22:07:13.392364+00	MT-1
