rror("Both arguments must be strings");\n+  }\n+\n+  const n = a.length;\n+  const m = b.length;\n+  const matrix = [];\n+\n+  for (let i = 0; i <= n; i++) {\n+    matrix[i] = [i];\n+  }\n+  for (let j = 0; j <= m; j++) {\n+    matrix[0][j] = j;\n+  }\n+\n+  for (let i = 1; i <= n; i++) {\n+    for (let j = 1; j <= m; j++) {\n+      const cost = a[i - 1] === b[j - 1] ? 0 : 1;\n+      matrix[i][j] = Math.min(\n+        matrix[i - 1][j] + 1,\n+        matrix[i][j - 1] + 1,\n+        matrix[i - 1][j - 1] + cost\n+      );\n+    }\n+  }\n+\n+  return matrix[n][m];\n+}\n+\n+module.exports = { formatTemperature, levenshteinDistance };\ndiff --git a/weather.js b/weather.js\nindex d8acb1a..0a2a9c6 100644\n--- a/weather.js\n+++ b/weather.js\n@@ -1,6 +1,6 @@\n "use strict";\n \n-const { formatTemperature } = require("./utils");\n+const { formatTemperature, levenshteinDistance } = require("./utils");\n \n /**\n  * @typedef {Object} WeatherData\n@@ -10,12 +10,60 @@ const { formatTemperature } = require("./utils");\n  * @property {string} unit       - "C" or "F"\n  */\n \n+/**\n+ * @typedef {Object} CityResolution\n+ * @property {string} city\n+ * @property {boolean} corrected\n+ */\n+\n const WEATHER_DB = {\n   Munich: { temperature: 18, condition: "Partly Cloudy" },\n   Berlin: { temperature: 22, condition: "Sunny" },\n   Hamburg: { temperature: 15, condition: "Rainy" },\n };\n \n+/**\n+ * Resolve a user-typed city name against the WEATHER_DB keys.\n+ * @param {string} query\n+ * @returns {CityResolution}\n+ * @throws {Error} if no suitable city is found\n+ */\n+function findCity(query) {\n+  if (WEATHER_DB[query]) {\n+    return { city: query, corrected: false };\n+  }\n+\n+  const keys = Object.keys(WEATHER_DB);\n+  const lowerQuery = query.toLowerCase();\n+\n+  for (const key of keys) {\n+    if (key.toLowerCase() === lowerQuery) {\n+      return { city: key, corrected: true };\n+    }\n+  }\n+\n+  let minDistance = Infinity;\n+  let bestKey = null;\n+\n+  for (const key of