art_f605e560-e31e-4622-81b0-ab1d2cb7c9fe_synthtest_MT1_20260715091521806540	f605e560-e31e-4622-81b0-ab1d2cb7c9fe	test-synth	Synthesized test file: .agentic_tests/test_MT1.test.js\nExecution status: passed\nRole in verdict: gated the verdict (passed)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { newGame, step } from '../src/game.js';\n\n// Deterministic rng: always picks the first free cell.\nconst rngZero = () => 0;\n\ndescribe('newGame score/highScore fields', () => {\n  test('newGame() with no arguments returns score 0 and highScore 0', () => {\n    const state = newGame();\n    assert.equal(state.score, 0);\n    assert.equal(state.highScore, 0);\n  });\n\n  test('newGame(rng, 90) returns fresh state with score 0 but highScore preserved at 90', () => {\n    const state = newGame(rngZero, 90);\n    assert.equal(state.score, 0);\n    assert.equal(state.highScore, 90);\n  });\n});\n\ndescribe('step() score/highScore accumulation', () => {\n  function makeEatingState(snakeLength, score, highScore) {\n    // Build a straight snake moving right, head at (10,10), body extending left.\n    const snake = [];\n    for (let i = 0; i < snakeLength; i += 1) {\n      snake.push({ x: 10 - i, y: 10 });\n    }\n    return {\n      snake,\n      direction: 'right',\n      food: { x: 11, y: 10 }, // directly in front of the head\n      gameOver: false,\n      score,\n      highScore,\n    };\n  }\n\n  test('eating food with a length-3 snake awards 40 points (10 x post-growth length of 4)', () => {\n    const state = makeEatingState(3, 0, 0);\n    const next = step(state, rngZero);\n    assert.equal(next.score, 40);\n  });\n\n  test('a second consecutive eat (length 4 -> 5) awards 50 more points, cumulative score 90', () => {\n    // Start already at score 40 (from a prior eat), snake now length 4.\n    const state = makeEatingState(4, 40, 40);\n  