ead.\n    const head2 = state.snake[0];\n    state = { ...state, food: { x: head2.x + 1, y: head2.y } };\n\n    const next = step(state, rngZero);\n\n    assert.equal(next.snake.length, 5);\n    assert.equal(next.score, 90);\n  });\n\n  test('after the score reaches 90, highScore is also 90', () => {\n    let state = newGame(rngZero, 0);\n    const head = state.snake[0];\n    state = { ...state, food: { x: head.x + 1, y: head.y } };\n\n    state = step(state, rngZero); // score 40\n\n    const head2 = state.snake[0];\n    state = { ...state, food: { x: head2.x + 1, y: head2.y } };\n\n    const next = step(state, rngZero); // score 90\n\n    assert.equal(next.score, 90);\n    assert.equal(next.highScore, 90);\n  });\n});\n\ndescribe('newGame reset after reaching a score', () => {\n  test('newGame(rng, 90) resets score to 0 but keeps highScore at 90', () => {\n    const state = newGame(rngZero, 90);\n    assert.equal(state.score, 0);\n    assert.equal(state.highScore, 90);\n  });\n});\n\ndescribe('non-eating step', () => {\n  test('a non-eating step does not change score or highScore', () => {\n    let state = newGame(rngZero, 0);\n    // Ensure food is NOT where the head will move next tick.\n    const head = state.snake[0];\n    state = { ...state, food: { x: head.x + 5, y: head.y + 5 }, score: 0, highScore: 0 };\n\n    const next = step(state, rngZero);\n\n    assert.equal(next.score, 0);\n    assert.equal(next.highScore, 0);\n  });\n});\n\ndescribe('game-over no-op path', () => {\n  test('step on a game-over state returns the exact same state object reference', () => {\n    const state = newGame(rngZero, 0);\n    const gameOverState = { ...state, gameOver: true };\n\n    const next = step(gameOverState, rngZero);\n\n    assert.equal(next, gameOverState);\n  });\n});\n	\N	2026-07-15 08:47:52.52041+00	MT1
