art_5ff5c011-c912-4234-ad14-f2143654ae4a_synthtest_MT4_20260715084943708227	5ff5c011-c912-4234-ad14-f2143654ae4a	test-synth	Synthesized test file: .agentic_tests/test_MT4.test.js\nExecution status: passed\nRole in verdict: counted as positive evidence (ungrounded — no IOExamples)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst __dirname = path.dirname(fileURLToPath(import.meta.url));\nconst cssPath = path.join(__dirname, '..', 'style.css');\nconst css = fs.readFileSync(cssPath, 'utf8');\n\n// Strip comments to avoid false matches inside /* ... */ blocks\nconst cssNoComments = css.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '');\n\nfunction getRuleBody(selectorRegex, source) {\n  // Find a rule block whose selector list matches the regex, return its declaration body (between { and })\n  const ruleRegex = /([^{}]+)\\{([^{}]*)\\}/g;\n  let match;\n  while ((match = ruleRegex.exec(source)) !== null) {\n    const selectorList = match[1];\n    const body = match[2];\n    if (selectorRegex.test(selectorList)) {\n      return { selectorList, body };\n    }\n  }\n  return null;\n}\n\ndescribe('MT4: Style the score and high score elements', () => {\n  test('style.css file exists and is non-empty', () => {\n    assert.equal(fs.existsSync(cssPath), true);\n    assert.equal(typeof css, 'string');\n    assert.ok(css.length > 0);\n  });\n\n  test('style.css contains a CSS rule targeting #score', () => {\n    const rule = getRuleBody(/#score\\b/, cssNoComments);\n    assert.ok(rule, 'expected a CSS rule with a selector referencing #score');\n    // ensure the rule body actually has at least one declaration (not left empty/unstyled)\n    const declarations = rule.body.split(';').map((d) => d.trim()).filter(Boolean);\n    assert.ok(declarations.length > 0, 'expected #score rule to contain at least one declaration');\n  });\n\n  test('style.css contains a CSS rule targeting #high-score', () => {\n    const rule = getRuleBody(/#high-score\\b/, cssNoComments);\n    assert.ok(rule, 'expected a CSS rule with a selector referencing #high-score');\n    const declarations = rule.body.split(';').map((d) => d.trim()).filter(Boolean);\n    assert.ok(declarations.length > 0, 'expected #high-score rule to contain at least one declaration');\n  });\n\n  test('#score and #high-score rules include layout/typography declarations (not left as browser defaults)', () => {\n    const scoreRule = getRuleBody(/#score\\b/, cssNoComments);\n    const highScoreRule = getRuleBody(/#high-score\\b/, cssNoComments);\n    assert.ok(scoreRule);\n    assert.ok(highScoreRule);\n\n    // Look for at least one relevant styling property (font, color, margin, spacing) in either\n    // the individual rule or a combined selector rule (e.g. "#score, #high-score { ... }")\n    const relevantPropertyPattern = /(font-size|font-weight|color|margin|padding|gap|display|align-items|justify-content)\\s*:/i;\n\n    assert.ok(\n      relevantPropertyPattern.test(scoreRule.body),\n      'expected #score rule to declare visual styling (font/color/spacing) properties'\n    );\n    assert.ok(\n      relevantPropertyPattern.test(highScoreRule.body),\n      'expected #high-score rule to declare visual styling (font/color/spacing) properties'\n    );\n  });\n\n  test('score and high score are laid out side-by-side above the board via a container or flex rules', () => {\n    // Following conventions used for header (flex layout), look either for a .scoreboard-like\n    // container rule using display: flex, or #score/#high-score themselves being inline/flex items.\n    const scoreboardRule = getRuleBody(/\\.scoreboard\\b/, cssNoComments);\n    const hasFlexContainer = scoreboardRule && /display\\s*:\\s*flex/i.test(scoreboardRule.body);\n\n    const scoreRule = getRuleBody(/#score\\b/, cssNoComments);\n    const highScoreRule = getRuleBody(/#high-score\\b/, cssNoComments);\n    const hasInlineDisplay = (scoreRule && /display\\s*:\\s*(inline|inline-block|flex)/i.test(scoreRule.body)) ||\n      (highScoreRule && /display\\s*:\\s*(inline|inline-block|flex)/i.test(highScoreRule.body));\n\n    assert.ok(\n      hasFlexContainer || hasInlineDisplay,\n      'expected either a container (e.g. .scoreboard) styled with display: flex, or #score/#high-score styled to sit side-by-side'\n    );\n  });\n});\n	\N	2026-07-15 08:49:43.708227+00	MT4
