art_5ff5c011-c912-4234-ad14-f2143654ae4a_synthtest_MT3_20260715084900089908	5ff5c011-c912-4234-ad14-f2143654ae4a	test-synth	Synthesized test file: .agentic_tests/test_MT3.test.js\nExecution status: passed\nRole in verdict: counted as positive evidence (ungrounded — no IOExamples)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\nimport { fileURLToPath } from 'node:url';\nimport { dirname, join } from 'node:path';\n\nconst __dirname = dirname(fileURLToPath(import.meta.url));\nconst htmlPath = join(__dirname, '..', 'index.html');\nconst html = readFileSync(htmlPath, 'utf8');\n\nfunction extractElement(html, id) {\n  // Matches <tag id="id" ...>content</tag> (non-greedy content, no nested same-tag assumed)\n  const regex = new RegExp(\n    `<([a-zA-Z0-9]+)[^>]*\\\\bid=["']${id}["'][^>]*>([\\\\s\\\\S]*?)<\\\\/\\\\1>`\n  );\n  const match = html.match(regex);\n  return match ? { tag: match[1], content: match[2].trim() } : null;\n}\n\ndescribe('index.html score and high-score markup', () => {\n  test('contains an element with id "score" with initial text "Score: 0"', () => {\n    const el = extractElement(html, 'score');\n    assert.ok(el, 'Expected an element with id="score" to exist in index.html');\n    assert.equal(el.content, 'Score: 0');\n  });\n\n  test('contains an element with id "high-score" with initial text "High score: 0"', () => {\n    const el = extractElement(html, 'high-score');\n    assert.ok(el, 'Expected an element with id="high-score" to exist in index.html');\n    assert.equal(el.content, 'High score: 0');\n  });\n\n  test('#score element appears before the #board canvas in document order', () => {\n    const scoreIndex = html.search(/id=["']score["']/);\n    const boardIndex = html.search(/<canvas[^>]*\\bid=["']board["']/);\n    assert.notEqual(scoreIndex, -1, 'Expected to find id="score" in index.html');\n    assert.notEqual(boardIndex, -1, 'Expected to find <canvas id="board"> in index.html');\n    assert.ok(scoreIndex < boardIndex, 'Expected #score to appear before #board canvas');\n  });\n\n  test('#high-score element appears before the #board canvas in document order', () => {\n    const highScoreIndex = html.search(/id=["']high-score["']/);\n    const boardIndex = html.search(/<canvas[^>]*\\bid=["']board["']/);\n    assert.notEqual(highScoreIndex, -1, 'Expected to find id="high-score" in index.html');\n    assert.notEqual(boardIndex, -1, 'Expected to find <canvas id="board"> in index.html');\n    assert.ok(highScoreIndex < boardIndex, 'Expected #high-score to appear before #board canvas');\n  });\n\n  test('#score and #high-score are both located inside the <header> element', () => {\n    const headerMatch = html.match(/<header[^>]*>([\\s\\S]*?)<\\/header>/);\n    assert.ok(headerMatch, 'Expected a <header> element in index.html');\n    const headerContent = headerMatch[1];\n    assert.ok(/id=["']score["']/.test(headerContent), '#score should be inside <header>');\n    assert.ok(/id=["']high-score["']/.test(headerContent), '#high-score should be inside <header>');\n  });\n});\n	\N	2026-07-15 08:49:00.089908+00	MT3
