art_61b22cd4-9f20-4b6e-9741-98f30565d022_synthtest_mt-1-game-logic_20260715112507423654	61b22cd4-9f20-4b6e-9741-98f30565d022	test-synth	Synthesized test file: .agentic_tests/test_mt_1_game_logic.test.js\nExecution status: passed\nRole in verdict: gated the verdict (passed)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { newGame, step } from '../src/game.js';\n\ndescribe('Game Logic - Scoring', () => {\n  test('newGame initializes score to 0', () => {\n    const state = newGame();\n    assert.equal(state.score, 0);\n  });\n\n  test('Eating food increases score by 10 * new length', () => {\n    // Case 1: given {'score': 0, 'snake_length': 3, 'eating': True} -> expect {'score': 40}\n    // We simulate this by creating a state where the head will move onto the food.\n    // Initial snake length is 3.\n    const state1 = {\n      snake: [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }],\n      direction: 'right',\n      food: { x: 11, y: 10 },\n      gameOver: false,\n      score: 0,\n    };\n    const result1 = step(state1);\n    // Snake grows to 4, score should be 0 + (10 * 4) = 40\n    assert.equal(result1.score, 40);\n\n    // Case 2: given {'score': 40, 'snake_length': 4, 'eating': True} -> expect {'score': 90}\n    const state2 = {\n      snake: [{ x: 11, y: 10 }, { x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }],\n      direction: 'right',\n      food: { x: 12, y: 10 },\n      gameOver: false,\n      score: 40,\n    };\n    const result2 = step(state2);\n    // Snake grows to 5, score should be 40 + (10 * 5) = 90\n    assert.equal(result2.score, 90);\n  });\n});\n	\N	2026-07-15 11:25:07.423654+00	mt-1-game-logic
