d grows the snake by one segment, spawns a new food, and awards\n+// points equal to 10 times the snake's new (post-growth) length.\n export function step(state, rng = Math.random) {\n   if (state.gameOver) return state;\n \n@@ -80,5 +85,10 @@ export function step(state, rng = Math.random) {\n   const snake = eating ? grown : grown.slice(0, -1);\n   const food = eating ? spawnFood(snake, rng) : state.food;\n \n-  return { ...state, snake, food };\n+  const newScore = eating ? state.score + 10 * snake.length : state.score;\n+  const newHighScore = eating\n+    ? Math.max(state.highScore, newScore)\n+    : state.highScore;\n+\n+  return { ...state, snake, food, score: newScore, highScore: newHighScore };\n }\ndiff --git a/src/ui.js b/src/ui.js\nindex 4342e0b..b5c32c0 100644\n--- a/src/ui.js\n+++ b/src/ui.js\n@@ -2,6 +2,7 @@\n // clock. All game rules live in src/game.js.\n \n import { COLS, ROWS, newGame, step, changeDirection } from './game.js';\n+import { formatScoreText, formatHighScoreText } from './format.js';\n \n const CELL = 20; // pixels\n const TICK_MS = 120;\n@@ -10,11 +11,14 @@ const canvas = document.getElementById('board');\n const context = canvas.getContext('2d');\n const statusElement = document.getElementById('status');\n const newGameButton = document.getElementById('new-game');\n+const scoreElement = document.getElementById('score');\n+const highScoreElement = document.getElementById('high-score');\n \n canvas.width = COLS * CELL;\n canvas.height = ROWS * CELL;\n \n let state = newGame();\n+let highScore = 0;\n \n function drawCell(cell, color) {\n   context.fillStyle = color;\n@@ -31,6 +35,9 @@ function render() {\n   });\n \n   statusElement.textContent = state.gameOver ? 'Game over!' : '';\n+  scoreElement.textContent = formatScoreText(state.score);\n+  highScoreElement.textContent = formatHighScoreText(Math.max(highScore, state.highScore));\n+  highScore = Math.max(highScore, state.highScore);\n }\n \n const KEY_TO_DIRECTION = {\n@@ -48,7 +55,7 @@ document.addEventListener('keydown', (event) => {\n });\n \n newGameButton.addEventListener('click', () => {\n-  state = newGame();\n+  state = newGame(undefined, highScore);\n });\n \n setInterval(() => {\ndiff --git a/test/game.test.js b/test/game.test.js\nindex 1c28d56..ef65ecc 100644\n--- a/test/game.test.js\n+++ b/test/game.test.js\n@@ -20,6 +20,8 @@ function state(overrides) {\n     direction: 'right',\n     food: { x: 15, y: 15 },\n     gameOver: false,\n+    score: 0,\n+    highScore: 0,\n     ...overrides,\n   };\n }\n@@ -140,3 +142,58 @@ test('step is a no-op once the game is over', () => {\n   const next = step(over);\n   assert.deepEqual(next, over);\n });\n+\n+test('newGame defaults score and highScore to 0', () => {\n+  const game = newGame(() => 0);\n+  assert.equal(game.score, 0);\n+  assert.equal(game.highScore, 0);\n+});\n+\n+test('newGame carries over a passed-in highScore while resetting score', () => {\n+  const game = newGame(() => 0, 90);\n+  assert.equal(game.score, 0);\n+  assert.equal(game.highScore, 90);\n+});\n+\n+test('eating food from length 3 to 4 awards 40 points', () => {\n+  const eating = state({ food: { x: 11, y: 10 } });\n+  const next = step(eating, () => 0);\n+  assert.equal(next.snake.length, 4);\n+  assert.equal(next.score, 40);\n+});\n+\n+test('eating food from length 9 to 10 awards 100 points', () => {\n+  const snake = [];\n+  for (let i = 0; i < 9; i += 1) snake.push({ x: 10 - i, y: 10 });\n+  const eating = state({ snake, food: { x: 11, y: 10 } });\n+  const next = step(eating, () => 0);\n+  assert.equal(next.snake.length, 10);\n+  assert.equal(next.score, 100);\n+});\n+\n+test('a normal (non-eating) move leaves score and highScore unchanged', () => {\n+  const moving = state({ score: 50, highScore: 90 });\n+  const next = step(moving);\n+  assert.equal(next.score, 50);\n+  assert.equal(next.highScore, 90);\n+});\n+\n+test('eating updates highScore when the new score exceeds it', () => {\n+  const eating = state({ food: { x: 11, y: 10 }, score: 0, highScore: 0 });\n+  const next = step(eating, () => 0);\n+  assert.equal(next.score, 40);\n+  assert.equal(next.highScore, 40);\n+});\n+\n+test('eating leaves highScore unchanged when the new score does not exceed it', () => {\n+  const eating = state({ food: { x: 11, y: 10 }, score: 0, highScore: 90 });\n+  const next = step(eating, () => 0);\n+  assert.equal(next.score, 40);\n+  assert.equal(next.highScore, 90);\n+});\n+\n+test('step is a no-op once the game is over, including score/highScore', () => {\n+  const over = state({ gameOver: true, score: 40, highScore: 90 });\n+  const next = step(over);\n+  assert.deepEqual(next, over);\n+});\n	\N	2026-07-15 11:34:32.72942+00	MT3
