art_647b0a25-92f2-46d0-b0cc-a89ef02dfcd8_synthtest_MT1_20260715113349804239	647b0a25-92f2-46d0-b0cc-a89ef02dfcd8	test-synth	Synthesized test file: .agentic_tests/test_MT1.test.js\nExecution status: passed\nRole in verdict: counted as positive evidence (ungrounded — no IOExamples)\nTrivial-guard: passed\n------------------------------------------------------------\n\n// Tests for: Add score and highScore tracking to game.js state,\n// and fix shared test fixture defaults.\n//\n// Framework: node:test + node:assert/strict (this repo does NOT use Jest).\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\n\nimport { newGame, step } from '../src/game.js';\n\n// Local fixture mirroring test/game.test.js's `state(overrides)` helper,\n// including the score/highScore defaults required by this microtask.\nfunction state(overrides) {\n  return {\n    snake: [\n      { x: 10, y: 10 },\n      { x: 9, y: 10 },\n      { x: 8, y: 10 },\n    ],\n    direction: 'right',\n    food: { x: 15, y: 15 },\n    gameOver: false,\n    score: 0,\n    highScore: 0,\n    ...overrides,\n  };\n}\n\ndescribe('newGame score/highScore defaults', () => {\n  test('newGame(rng) returns score 0 and highScore 0 when no highScore argument is given', () => {\n    const game = newGame(() => 0);\n    assert.equal(game.score, 0);\n    assert.equal(game.highScore, 0);\n  });\n\n  test('newGame(rng, 90) resets score to 0 but carries over highScore 90', () => {\n    const game = newGame(() => 0, 90);\n    assert.equal(game.score, 0);\n    assert.equal(game.highScore, 90);\n  });\n});\n\ndescribe('step() scoring on eating', () => {\n  test('eating that grows the snake from length 3 to 4 increases score by 40', () => {\n    const eating = state({ food: { x: 11, y: 10 } });\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, 4);\n    assert.equal(next.score, eating.score + 40);\n    assert.equal(next.score, 40);\n  });\n\n  test('eating that grows the snake from length 9 to 10 increases score by 100', () => {\n    const snake = [];\n    for (let i = 0; i < 9; i += 1) snake.push({ x: 10 - i, y: 10 });\n    const eating = state({ snake, food: { x: 11, y: 10 } });\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, 10);\n    assert.equal(next.score, eating.score + 100);\n    assert.equal(next.score, 100);\n  });\n\n  test('eating food still grows the snake by exactly one segment', () => {\n    const eating = state({ food: { x: 11, y: 10 } });\n    const before = eating.snake.length;\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, before + 1);\n  });\n});\n\ndescribe('step() leaves score/highScore unchanged on a normal move', () => {\n  test('a non-eating move leaves score and highScore unchanged from the input state', () => {\n    const moving = state({ score: 50, highScore: 90 });\n    const next = step(moving);\n    assert.equal(next.score, moving.score);\n    assert.equal(next.highScore, moving.highScore);\n    assert.equal(next.score, 50);\n    assert.equal(next.highScore, 90);\n  });\n});\n\ndescribe('step() highScore updates', () => {\n  test('highScore updates to match score when the new score exceeds the previous highScore', () => {\n    const eating = state({ food: { x: 11, y: 10 }, score: 0, highScore: 0 });\n    const next = step(eating, () => 0);\n    assert.equal(next.score, 40);\n    assert.equal(next.highScore, 40);\n  });\n\n  test('highScore stays unchanged when the new score does not exceed it', () => {\n    const eating = state({ food: { x: 11, y: 10 }, score: 0, highScore: 90 });\n    const next = step(eating, () => 0);\n    assert.equal(next.score, 40);\n    assert.equal(next.highScore, 90);\n  });\n});\n\ndescribe('step() no-op on game over', () => {\n  test('step on a gameOver state returns the exact same state object unchanged, including score/highScore', () => {\n    const over = state({ gameOver: true, score: 40, highScore: 90 });\n    const next = step(over);\n    assert.deepEqual(next, over);\n    assert.equal(next.score, over.score);\n    assert.equal(next.highScore, over.highScore);\n  });\n});\n	\N	2026-07-15 11:33:49.804239+00	MT1
