art_647b0a25-92f2-46d0-b0cc-a89ef02dfcd8_synthtest_MT3_20260715113516791026	647b0a25-92f2-46d0-b0cc-a89ef02dfcd8	test-synth	Synthesized test file: .agentic_tests/test_MT3.test.js\nExecution status: failed\nRole in verdict: advisory — failure ignored (ungrounded, no IOExamples; Track A decided)\nTrivial-guard: passed\n------------------------------------------------------------\n\n// Tests for: Wire score and high-score display into ui.js render loop and\n// New game handler.\n//\n// src/ui.js touches the DOM (document.getElementById, canvas, etc.) at\n// module load time, so it cannot be `import`ed directly under plain Node.\n// Instead we verify the underlying contract that ui.js's render() and\n// New-game handler rely on:\n//   - render() sets score/high-score text via formatScoreText/formatHighScoreText\n//     applied to state.score / Math.max(highScore, state.highScore), mirroring\n//     the exact code in ui.js's render().\n//   - The New game handler calls newGame(undefined, highScore), so the\n//     underlying game state's highScore is preserved (not reset to 0) across\n//     a reset, matching the "reach 90, new game, stays 90" example.\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { newGame, step } from '../src/game.js';\nimport { formatScoreText, formatHighScoreText } from '../src/format.js';\n\n// Deterministic rng so spawnFood is predictable across ticks.\nfunction makeRng(sequence) {\n  let i = 0;\n  return () => {\n    const value = sequence[i % sequence.length];\n    i += 1;\n    return value;\n  };\n}\n\n// Drives the snake in a straight line, placing food directly ahead of the\n// head every tick so it always eats and grows by exactly one segment per\n// tick. This gives us score = 10 * length after each eat, matching the\n// game.js contract ("10 x length, first food = 40").\nfunction eatOnce(state, rng) {\n  const head = state.snake[0];\n  const foodCell = { x: head.x + 1, y: head.y };\n  const forcedState = { ...state, food: foodCell };\n  return step(forcedState, rng);\n}\n\ndescribe('New game handler preserves high score across reset (ui.js contract)', () => {\n  test('reaching a score of 90 then starting New game keeps high score at 90', () => {\n    const rng = makeRng([0]);\n    let state = newGame(rng);\n\n    // Eat food repeatedly until the score reaches 90, mirroring what would\n    // happen during real play before the "New game" button is clicked.\n    while (state.score < 90) {\n      state = eatOnce(state, rng);\n    }\n\n    assert.equal(state.score, 90);\n    assert.equal(state.highScore, 90);\n\n    // Simulate ui.js's module-level `highScore` variable, updated the same\n    // way render() does: highScore = Math.max(highScore, state.highScore).\n    let highScore = 0;\n    highScore = Math.max(highScore, state.highScore);\n    assert.equal(highScore, 90);\n\n    // Simulate clicking "New game": ui.js calls newGame(undefined, highScore)\n    // instead of newGame() with no high score argument, so the high score\n    // survives the reset while score itself goes back to 0.\n    state = newGame(undefined, highScore);\n\n    assert.equal(state.score, 0);\n    assert.equal(state.highScore, 90);\n\n    // The high-score text that render() would produce for the high-score\n    // element must reflect the value 90, not reset to 0.\n    const displayedHighScoreText = formatHighScoreText(Math.max(highScore, state.highScore));\n    assert.equal(displayedHighScoreText, 'High score: 90');\n  });\n\n  test('newGame with no highScore argument defaults the session high score to 0', () => {\n    const state = newGame(undefined);\n    assert.equal(state.highScore, 0);\n  });\n});\n\ndescribe('render() text contract: score and high-score elements are always set from formatting helpers', () => {\n  test('first food eaten (snake grows from 3 to 4) yields a score of 40, formatted via formatScoreText', () => {\n    const rng = makeRng([0]);\n    const initial = newGame(rng);\n    assert.equal(initial.snake.length, 3);\n    assert.equal(initial.score, 0);\n\n    const afterFirstFood = eatOnce(initial, rng);\n\n    assert.equal(afterFirstFood.snake.length, 4);\n    assert.equal(afterFirstFood.score, 40);\n\n    // This is exactly what ui.js's render() assigns to scoreElement.textContent.\n    const scoreText = formatScoreText(afterFirstFood.score);\n    assert.equal(scoreText, 'Score: 40');\n    assert.notEqual(scoreText, '');\n    assert.notEqual(scoreText, undefined);\n  });\n\n  test('second food eaten yields a score of 50, formatted via formatScoreText', () => {\n    const rng = makeRng([0]);\n    let state = newGame(rng);\n    state = eatOnce(state, rng); // -> 40\n    state = eatOnce(state, rng); // -> 50\n\n    assert.equal(state.score, 50);\n    assert.equal(formatScoreText(state.score), 'Score: 50');\n  });\n\n  test('render()-equivalent computation never leaves score or high-score text blank/unset during normal play', () => {\n    const rng = makeRng([0]);\n    let state = newGame(rng);\n    let highScore = 0;\n\n    for (let i = 0; i < 3; i += 1) {\n      state = eatOnce(state, rng);\n\n      // Mirror render()'s exact statements from ui.js:\n      //   scoreElement.textContent = formatScoreText(state.score);\n      //   highScoreElement.textContent = formatHighScoreText(Math.max(highScore, state.highScore));\n      //   highScore = Math.max(highScore, state.highScore);\n      const scoreText = formatScoreText(state.score);\n      const highScoreText = formatHighScoreText(Math.max(highScore, state.highScore));\n      highScore = Math.max(highScore, state.highScore);\n\n      assert.equal(typeof scoreText, 'string');\n      assert.equal(typeof highScoreText, 'string');\n      assert.ok(scoreText.length > 0);\n      assert.ok(highScoreText.length > 0);\n      assert.notEqual(scoreText, undefined);\n      assert.notEqual(highScoreText, undefined);\n    }\n  });\n\n  test('formatScoreText and formatHighScoreText both return strings for a fresh game state (score 0)', () => {\n    const state = newGame(undefined, 0);\n    const scoreText = formatScoreText(state.score);\n    const highScoreText = formatHighScoreText(Math.max(0, state.highScore));\n\n    assert.equal(scoreText, 'Score: 0');\n    assert.equal(highScoreText, 'High score: 0');\n  });\n});\n	\N	2026-07-15 11:35:16.791026+00	MT3
