art_647b0a25-92f2-46d0-b0cc-a89ef02dfcd8_synthtest_MT4_20260715113559192692	647b0a25-92f2-46d0-b0cc-a89ef02dfcd8	test-synth	Synthesized test file: .agentic_tests/test_MT4.test.js\nExecution status: passed\nRole in verdict: counted as positive evidence (ungrounded — no IOExamples)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\nimport { fileURLToPath } from 'node:url';\nimport path from 'node:path';\n\nconst __dirname = path.dirname(fileURLToPath(import.meta.url));\nconst indexHtmlPath = path.join(__dirname, '..', 'index.html');\nconst styleCssPath = path.join(__dirname, '..', 'style.css');\n\nconst html = readFileSync(indexHtmlPath, 'utf8');\nconst css = readFileSync(styleCssPath, 'utf8');\n\nfunction extractTag(source, tagName) {\n  const openRe = new RegExp(`<${tagName}[^>]*>`, 'i');\n  const closeRe = new RegExp(`</${tagName}>`, 'i');\n  const openMatch = openRe.exec(source);\n  const closeMatch = closeRe.exec(source);\n  if (!openMatch || !closeMatch) return null;\n  const start = openMatch.index;\n  const end = closeMatch.index + closeMatch[0].length;\n  return source.slice(start, end);\n}\n\ndescribe('MT4: score and high-score markup in index.html', () => {\n  const headerContent = extractTag(html, 'header');\n\n  test('index.html contains a <header> element', () => {\n    assert.ok(headerContent, 'Expected to find a <header>...</header> block in index.html');\n  });\n\n  test('index.html contains an element with id="score" inside <header>', () => {\n    assert.ok(headerContent, 'header must exist to check its contents');\n    assert.match(headerContent, /id\\s*=\\s*["']score["']/);\n  });\n\n  test('index.html contains an element with id="high-score" inside <header>', () => {\n    assert.ok(headerContent, 'header must exist to check its contents');\n    assert.match(headerContent, /id\\s*=\\s*["']high-score["']/);\n  });\n\n  test('#score and #high-score are NOT found outside of <header> only (sanity: they exist in full document too)', () => {\n    assert.match(html, /id\\s*=\\s*["']score["']/);\n    assert.match(html, /id\\s*=\\s*["']high-score["']/);\n  });\n\n  test('#score and #high-score both appear before <canvas id="board"> in document order', () => {\n    const scoreIndex = html.search(/id\\s*=\\s*["']score["']/);\n    const highScoreIndex = html.search(/id\\s*=\\s*["']high-score["']/);\n    const boardMatch = /<canvas[^>]*id\\s*=\\s*["']board["'][^>]*>/i.exec(html);\n\n    assert.notEqual(scoreIndex, -1, '#score element not found');\n    assert.notEqual(highScoreIndex, -1, '#high-score element not found');\n    assert.ok(boardMatch, '<canvas id="board"> not found');\n\n    const boardIndex = boardMatch.index;\n\n    assert.ok(scoreIndex < boardIndex, '#score must appear before <canvas id="board">');\n    assert.ok(highScoreIndex < boardIndex, '#high-score must appear before <canvas id="board">');\n  });\n\n  test('the #score and #high-score elements are located within the <header> element bounds', () => {\n    const headerOpenMatch = /<header[^>]*>/i.exec(html);\n    const headerCloseMatch = /<\\/header>/i.exec(html);\n    assert.ok(headerOpenMatch, '<header> opening tag not found');\n    assert.ok(headerCloseMatch, '</header> closing tag not found');\n\n    const headerStart = headerOpenMatch.index;\n    const headerEnd = headerCloseMatch.index + headerCloseMatch[0].length;\n\n    const scoreIndex = html.search(/id\\s*=\\s*["']score["']/);\n    const highScoreIndex = html.search(/id\\s*=\\s*["']high-score["']/);\n\n    assert.ok(scoreIndex > headerStart && scoreIndex < headerEnd, '#score must be located inside <header>...</header>');\n    assert.ok(highScoreIndex > headerStart && highScoreIndex < headerEnd, '#high-score must be located inside <header>...</header>');\n  });\n});\n\ndescribe('MT4: score and high-score styling in style.css', () => {\n  test('style.css contains a rule selector referencing #score', () => {\n    assert.match(css, /#score/);\n  });\n\n  test('style.css contains a rule selector referencing #high-score', () => {\n    assert.match(css, /#high-score/);\n  });\n});\n	\N	2026-07-15 11:35:59.192692+00	MT4
