art_c57057ed-ffae-48e7-8b49-d4f4635f276c_synthtest_implement_scoring_logic_20260715122113321552	c57057ed-ffae-48e7-8b49-d4f4635f276c	test-synth	Synthesized test file: .agentic_tests/test_implement_scoring_logic.test.js\nExecution status: passed\nRole in verdict: gated the verdict (passed)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { newGame, step } from '../src/game.js';\n\ndescribe('Scoring Logic', () => {\n  test('newGame initializes score to 0', () => {\n    const state = newGame();\n    assert.equal(state.score, 0);\n  });\n\n  test('Eating food increases score by 10 * new length', () => {\n    // Example 1: given {'currentScore': 0, 'lengthAfterEating': 4} -> expect 40\n    // Initial snake length is 3. Eating food makes it 4.\n    const state1 = {\n      snake: [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }],\n      direction: 'right',\n      food: { x: 11, y: 10 },\n      gameOver: false,\n      score: 0,\n    };\n    const nextState1 = step(state1);\n    assert.equal(nextState1.score, 40);\n\n    // Example 2: given {'currentScore': 40, 'lengthAfterEating': 5} -> expect 90\n    // Snake length is 4. Eating food makes it 5.\n    const state2 = {\n      snake: [{ x: 11, y: 10 }, { x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }],\n      direction: 'right',\n      food: { x: 12, y: 10 },\n      gameOver: false,\n      score: 40,\n    };\n    const nextState2 = step(state2);\n    assert.equal(nextState2.score, 90);\n  });\n\n  test('Score remains unchanged when not eating', () => {\n    // Example: given {'currentScore': 40, 'eating': False} -> expect 40\n    const state = {\n      snake: [{ x: 11, y: 10 }, { x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }],\n      direction: 'right',\n      food: { x: 15, y: 15 }, // Food is far away\n      gameOver: false,\n      score: 40,\n    };\n    const nextState = step(state);