art_f450c965-4bb5-4198-b726-74c7969741b9_synthtest_MT1_20260715114507709056	f450c965-4bb5-4198-b726-74c7969741b9	test-synth	Synthesized test file: .agentic_tests/test_MT1.test.js\nExecution status: passed\nRole in verdict: gated the verdict (passed)\nTrivial-guard: passed\n------------------------------------------------------------\n\n// Tests for: Add score and highScore fields to game state and update scoring in step()\n// Framework: node:test + node:assert (this repo does NOT use Jest)\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\n\nimport { newGame, step } from '../src/game.js';\n\n// Local fixture helper mirroring test/game.test.js's `state()` helper,\n// with default score/highScore fields as specified in the microtask.\nfunction state(overrides) {\n  return {\n    snake: [\n      { x: 10, y: 10 },\n      { x: 9, y: 10 },\n      { x: 8, y: 10 },\n    ],\n    direction: 'right',\n    food: { x: 15, y: 15 },\n    gameOver: false,\n    score: 0,\n    highScore: 0,\n    ...overrides,\n  };\n}\n\ndescribe('newGame() score/highScore defaults', () => {\n  test('newGame() with no previous high score returns score 0 and highScore 0', () => {\n    const game = newGame(() => 0);\n    assert.equal(game.score, 0);\n    assert.equal(game.highScore, 0);\n  });\n\n  test('newGame(rng, previousHighScore) resets score to 0 but preserves the given high score', () => {\n    const game = newGame(() => 0, 90);\n    assert.equal(game.score, 0);\n    assert.equal(game.highScore, 90);\n  });\n});\n\ndescribe('step() scoring on eating food', () => {\n  test('eating food when snake length is 3 (growing to 4) sets score to 40', () => {\n    const eating = state({ food: { x: 11, y: 10 } });\n    const next = step(eating, () => 0);\n    assert.equal(next.snake.length, 4);\n    assert.equal(next.score, 40);\n  });\n\n  test('eating food again from an already-scored 40 (growing 4 -> 5) yields cumulative score 90', () => {\n    const alreadyScored = state({\n      snake: [\n        { x: 10, y: 10 },\n        { x: 9, y: 10 },\n        { x: 8, y: 10 },\n        { x: 7, y: 10 },\n      ],\n      food: { x: 11, y: 10 },\n      score: 40,\n      highScore: 40,\n    });\n    const next = step(alreadyScored, () => 0);\n    assert.equal(next.snake.length, 5);\n    assert.equal(next.score, 90);\n  });\n});\n\ndescribe('step() score/highScore pass-through when not eating', () => {\n  test('step() with no food eaten this tick keeps score and highScore unchanged', () => {\n    const notEating = state({ score: 25, highScore: 60, food: { x: 15, y: 15 } });\n    const next = step(notEating, () => 0);\n    assert.equal(next.score, 25);\n    assert.equal(next.highScore, 60);\n  });\n});\n\ndescribe('step() highScore updates', () => {\n  test('highScore updates to match score when new score exceeds previous highScore', () => {\n    const fresh = state({ food: { x: 11, y: 10 }, score: 0, highScore: 0 });\n    const next = step(fresh, () => 0);\n    assert.equal(next.score, 40);\n    assert.equal(next.highScore, 40);\n  });\n\n  test('highScore does not lower when current score is still below a previously higher highScore', () => {\n    const belowHighScore = state({ food: { x: 11, y: 10 }, score: 0, highScore: 90 });\n    const next = step(belowHighScore, () => 0);\n    assert.equal(next.score, 40);\n    assert.equal(next.highScore, 90);\n  });\n});\n\ndescribe('step() no-op behaviour once gameOver is true', () => {\n  test('step() returns the same state object unchanged, including score/highScore, when gameOver is true', () => {\n    const over = state({ gameOver: true, score: 55, highScore: 100 });\n    const next = step(over);\n    assert.deepEqual(next, over);\n    assert.equal(next.score, 55);\n    assert.equal(next.highScore, 100);\n  });\n});\n	\N	2026-07-15 11:45:07.709056+00	MT1
