ows the snake by one segment and spawns a new food. Eating also\n+// increases the score by 10 times the snake's new length, and updates the\n+// high score when the new score surpasses it.\n export function step(state, rng = Math.random) {\n   if (state.gameOver) return state;\n \n@@ -80,5 +85,13 @@ export function step(state, rng = Math.random) {\n   const snake = eating ? grown : grown.slice(0, -1);\n   const food = eating ? spawnFood(snake, rng) : state.food;\n \n-  return { ...state, snake, food };\n+  if (eating) {\n+    const newLength = snake.length;\n+    const points = 10 * newLength;\n+    const newScore = (state.score || 0) + points;\n+    const newHighScore = Math.max(state.highScore || 0, newScore);\n+    return { ...state, snake, food, score: newScore, highScore: newHighScore };\n+  }\n+\n+  return { ...state, snake, food, score: state.score, highScore: state.highScore };\n }\ndiff --git a/src/ui.js b/src/ui.js\nindex 4342e0b..6b15882 100644\n--- a/src/ui.js\n+++ b/src/ui.js\n@@ -10,11 +10,14 @@ const canvas = document.getElementById('board');\n const context = canvas.getContext('2d');\n const statusElement = document.getElementById('status');\n const newGameButton = document.getElementById('new-game');\n+const scoreValueElement = document.getElementById('score-value');\n+const highScoreValueElement = document.getElementById('high-score-value');\n \n canvas.width = COLS * CELL;\n canvas.height = ROWS * CELL;\n \n-let state = newGame();\n+let highScore = 0;\n+let state = newGame(Math.random, highScore);\n \n function drawCell(cell, color) {\n   context.fillStyle = color;\n@@ -33,6 +36,11 @@ function render() {\n   statusElement.textContent = state.gameOver ? 'Game over!' : '';\n }\n \n+function renderScore() {\n+  scoreValueElement.textContent = state.score;\n+  highScoreValueElement.textContent = highScore;\n+}\n+\n const KEY_TO_DIRECTION = {\n   ArrowUp: 'up',\n   ArrowDown: 'down',\n@@ -48,12 +56,16 @@ document.addEventListener('keydown', (event) => {\n });\n \n newGameButton.addEventListener('click', () => {\n-  state = newGame();\n+  state = newGame(Math.random, highScore);\n+  renderScore();\n });\n \n setInterval(() => {\n   state = step(state);\n+  highScore = state.highScore;\n   render();\n+  renderScore();\n }, TICK_MS);\n \n render();\n+renderScore();\ndiff --git a/test/game.test.js b/test/game.test.js\nindex 1c28d56..ed6efb4 100644\n--- a/test/game.test.js\n+++ b/test/game.test.js\n@@ -20,6 +20,8 @@ function state(overrides) {\n     direction: 'right',\n     food: { x: 15, y: 15 },\n     gameOver: false,\n+    score: 0,\n+    highScore: 0,\n     ...overrides,\n   };\n }\n	\N	2026-07-15 11:45:24.782736+00	MT2
