art_f450c965-4bb5-4198-b726-74c7969741b9_synthtest_MT3_20260715114759291831	f450c965-4bb5-4198-b726-74c7969741b9	test-synth	Synthesized test file: .agentic_tests/test_MT3.test.js\nExecution status: passed\nRole in verdict: counted as positive evidence (ungrounded — no IOExamples)\nTrivial-guard: passed\n------------------------------------------------------------\n\nimport { test, describe } from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst __dirname = path.dirname(fileURLToPath(import.meta.url));\nconst cssPath = path.join(__dirname, '..', 'style.css');\nconst css = fs.readFileSync(cssPath, 'utf8');\n\n// Strip comments to simplify rule-block extraction.\nconst cssNoComments = css.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '');\n\n/**\n * Extracts the contents of the first CSS rule block whose selector list\n * matches the given selector (exact match on a comma-separated selector,\n * ignoring surrounding whitespace/newlines).\n */\nfunction getRuleBlock(cssText, selector) {\n  // Match "selector1, selector2 { ... }" blocks, selectors possibly split across lines.\n  const ruleRegex = /([^{}]+)\\{([^{}]*)\\}/g;\n  let match;\n  while ((match = ruleRegex.exec(cssText)) !== null) {\n    const rawSelectors = match[1]\n      .split(',')\n      .map((s) => s.replace(/\\s+/g, ' ').trim());\n    if (rawSelectors.includes(selector)) {\n      return match[2];\n    }\n  }\n  return null;\n}\n\ndescribe('MT3: Style the scoreboard display', () => {\n  test('style.css exists and is readable', () => {\n    assert.equal(fs.existsSync(cssPath), true);\n    assert.equal(typeof css, 'string');\n    assert.ok(css.length > 0);\n  });\n\n  test('style.css contains a rule targeting #scoreboard', () => {\n    const block = getRuleBlock(cssNoComments, '#scoreboard');\n    assert.notEqual(block, null, 'expected a CSS rule with selector #scoreboard');\n  });\n\n  test('#scoreboard rule applies layout/spacing styling consistent with header styles', () => {\n    const headerBlock = getRuleBlock(cssNoComments, 'header');\n    const scoreboardBlock = getRuleBlock(cssNoComments, '#scoreboard');\n\n    assert.notEqual(headerBlock, null, 'expected an existing header rule to compare against');\n    assert.notEqual(scoreboardBlock, null, 'expected a #scoreboard rule');\n\n    // Layout properties used by the existing header rule.\n    const layoutProps = ['display', 'align-items', 'justify-content'];\n    const headerHasLayout = layoutProps.some((prop) =>\n      new RegExp(`(^|;|\\\\s)${prop}\\\\s*:`).test(headerBlock)\n    );\n    assert.equal(headerHasLayout, true, 'sanity check: header rule should use layout props');\n\n    const scoreboardHasLayoutProp = layoutProps.some((prop) =>\n      new RegExp(`(^|;|\\\\s)${prop}\\\\s*:`).test(scoreboardBlock)\n    );\n    assert.equal(\n      scoreboardHasLayoutProp,\n      true,\n      'expected #scoreboard to declare at least one layout property (display/align-items/justify-content) like header'\n    );\n\n    // Spacing property (margin/gap/padding) consistent with header's margin usage.\n    const spacingProps = ['margin', 'gap', 'padding'];\n    const scoreboardHasSpacing = spacingProps.some((prop) =>\n      new RegExp(`(^|;|\\\\s)${prop}(-[a-z]+)?\\\\s*:`).test(scoreboardBlock)\n    );\n    assert.equal(\n      scoreboardHasSpacing,\n      true,\n      'expected #scoreboard to declare spacing (margin/gap/padding) similar to header'\n    );\n  });\n\n  test('style.css styles #score-value and #high-score-value to visually distinguish values from labels', () => {\n    // These selectors may be combined (e.g. "#score-value,\\n#high-score-value { ... }")\n    // or defined separately; check both possibilities.\n    const combinedBlock = getRuleBlock(cssNoComments, '#score-value,\\n#high-score-value')\n      || getRuleBlock(cssNoComments, '#score-value, #high-score-value');\n\n    const scoreValueBlock = combinedBlock || getRuleBlock(cssNoComments, '#score-value');\n    const highScoreValueBlock = combinedBlock || getRuleBlock(cssNoComments, '#high-score-value');\n\n    assert.notEqual(\n      scoreValueBlock,\n      null,\n      'expected a CSS rule targeting #score-value'\n    );\n    assert.notEqual(\n      highScoreValueBlock,\n      null,\n      'expected a CSS rule targeting #high-score-value'\n    );\n\n    // Visual distinction typically comes via font-weight and/or color differing from\n    // the plain text styling of #scoreboard itself.\n    const distinguishingProps = ['font-weight', 'color', 'font-size', 'font-style'];\n\n    const scoreValueDistinguishes = distinguishingProps.some((prop) =>\n      new RegExp(`(^|;|\\\\s)${prop}\\\\s*:`).test(scoreValueBlock)\n    );\n    const highScoreValueDistinguishes = distinguishingProps.some((prop) =>\n      new RegExp(`(^|;|\\\\s)${prop}\\\\s*:`).test(highScoreValueBlock)\n    );\n\n    assert.equal(\n      scoreValueDistinguishes,\n      true,\n      'expected #score-value styling to include a distinguishing property (font-weight/color/font-size/font-style)'\n    );\n    assert.equal(\n      highScoreValueDistinguishes,\n      true,\n      'expected #high-score-value styling to include a distinguishing property (font-weight/color/font-size/font-style)'\n    );\n  });\n\n  test('#score-value/#high-score-value styling differs from plain #scoreboard text styling', () => {\n    const scoreboardBlock = getRuleBlock(cssNoComments, '#scoreboard');\n    const combinedBlock = getRuleBlock(cssNoComments, '#score-value,\\n#high-score-value')\n      || getRuleBlock(cssNoComments, '#score-value, #high-score-value')\n      || getRuleBlock(cssNoComments, '#score-value');\n\n    assert.notEqual(scoreboardBlock, null);\n    assert.notEqual(combinedBlock, null);\n\n    // The value spans should declare at least one property not present (or different)\n    // in the parent #scoreboard rule, indicating visual distinction from the label text.\n    const normalize = (block) =>\n      block\n        .split(';')\n        .map((decl) => decl.trim())\n        .filter(Boolean);\n\n    const scoreboardDecls = new Set(normalize(scoreboardBlock));\n    const valueDecls = normalize(combinedBlock);\n\n    const hasDistinctDeclaration = valueDecls.some((decl) => !scoreboardDecls.has(decl));\n    assert.equal(\n      hasDistinctDeclaration,\n      true,\n      'expected value spans to declare styling distinct from the surrounding #scoreboard text styling'\n    );\n  });\n});\n	\N	2026-07-15 11:47:59.291831+00	MT3
