ree = [];\n  for (let y = 0; y < 20; y += 1) {\n    for (let x = 0; x < 20; x += 1) {\n      if (!snake.some((s) => s.x === x && s.y === y)) free.push({ x, y });\n    }\n  }\n  const index = free.findIndex((c) => c.x === target.x && c.y === target.y);\n  assert.ok(index !== -1, 'target cell must be free');\n  // spawnFood does free[Math.floor(rng() * free.length)]; pick rng() so that\n  // Math.floor(rng() * free.length) === index.\n  const rngValue = index / free.length;\n  const rng = () => rngValue;\n  // sanity: confirm this rng really reproduces the intended spawn, using the\n  // real (already covered elsewhere) spawnFood implementation.\n  const spawned = spawnFood(snake, rng);\n  assert.deepEqual(spawned, target);\n  return rng;\n}\n\nconst INITIAL_SNAKE = [\n  { x: 10, y: 10 },\n  { x: 9, y: 10 },\n  { x: 8, y: 10 },\n];\n\n// Loads a fresh copy of src/ui.js against a fresh fake DOM and a controllable\n// rng, so eating food is deterministic. Each call re-imports the module\n// (cache-busted) so ui.js's closure-scoped `highScore`/`state` variables\n// start fresh.\nasync function loadUi({ rng = () => 0 } = {}) {\n  const dom = installFakeDom();\n  global.Math = Object.create(Math);\n  global.Math.random = rng;\n\n  const modUrl = `${path.join(repoRoot, 'src', 'ui.js')}?t=${Date.now()}-${Math.random()}`;\n  await import(modUrl);\n\n  return dom;\n}\n\n// ---- Acceptance criteria tests --------------------------------------------\n\ndescribe('scoreboard rendering on page load', () => {\n  test("on page load, 'score-value' and 'high-score-value' both show 0", async () => {\n    const dom = await loadUi();\n    assert.equal(dom.elements['score-value'].textContent, 0);\n    assert.equal(dom.elements['high-score-value'].textContent, 0);\n  });\n});\n\ndescribe('scoreboard updates as the snake eats food', () => {\n  test('after eating o\n… [542 chars truncated — narrow your query or read a specific line range] …\ns 90', async () => {\n    const dom = await loadUi(