+  };\n+}\n+\n+module.exports = { loadConfig };\ndiff --git a/main.js b/main.js\nindex 4572150..4ea93eb 100644\n--- a/main.js\n+++ b/main.js\n@@ -1,15 +1,75 @@\n "use strict";\n \n const { getWeather } = require("./weather");\n+const { loadConfig } = require("./config");\n \n-const inputCity = "Munich";\n+/**\n+ * Parse CLI arguments into city tokens and an optional unit flag.\n+ * @param {string[]} argv - process.argv.slice(2)\n+ * @returns {{ cities: string[], unit: string|null }}\n+ */\n+function parseArgs(argv) {\n+  const cities = [];\n+  let unit = null;\n \n-try {\n-  const result = getWeather(inputCity);\n-  console.log(`Weather in ${result.city}: ${result.temperature}°${result.unit}, ${result.condition}`);\n-  if (result.corrected) {\n-    console.log(`corrected "${inputCity}" -> "${result.city}"`);\n+  for (let i = 0; i < argv.length; i++) {\n+    if (argv[i] === "--unit") {\n+      unit = argv[i + 1];\n+      i++;\n+    } else {\n+      cities.push(argv[i]);\n+    }\n   }\n-} catch (err) {\n-  console.error(err.message);\n+\n+  return { cities, unit };\n+}\n+\n+function main() {\n+  const { cities, unit: cliUnit } = parseArgs(process.argv.slice(2));\n+\n+  let config;\n+  try {\n+    config = loadConfig(process.cwd());\n+  } catch (err) {\n+    console.error(err.message);\n+    process.exit(1);\n+    return;\n+  }\n+\n+  const effectiveUnit = cliUnit || config.defaultUnit || "C";\n+\n+  if (cities.length === 0) {\n+    console.error("Usage: node main.js <city> [<city> ...] [--unit C|F]");\n+    process.exit(1);\n+    return;\n+  }\n+\n+  let anyFailed = false;\n+\n+  for (const cityToken of cities) {\n+    try {\n+      let result;\n+      if (Object.prototype.hasOwnProperty.call(config.aliases, cityToken)) {\n+        const canonical = config.aliases[cityToken];\n+        result = getWeather(canonical, effectiveUnit);\n+        result.corrected = false;\n+      } else {\n+        result = getWeather(cityToken, effectiveUnit);\n+      }\n+\n+      console.log(\n+        `Weather in ${result.city}: ${result.temperature}°${result.unit}, ${result.condition}`\n+      );\n+      if (result.corrected) {\n+        console.log(`corrected "${cityToken}" -> "${result.city}"`);\n+      }\n+    } catch (err) {\n+      console.error(err.message);\n+      anyFailed = true;\n+    }\n+  }\n+\n+  process.exit(anyFailed ? 1 : 0);\n }\n+\n+main();\ndiff --git a/tests/weather.test.js b/tests/weather.test.js\nindex 0327db9..07816b3 100644\n--- a/tests/weather.test.js\n+++ b/tests/weather.test.js\n@@ -1,7 +1,15 @@\n "use strict";\n \n-const { levenshteinDistance } = require("../utils");\n+const { levenshteinDistance, formatTemperature } = require("../utils");\n const { findCity, getWeather } = require("../weather");\n+const { loadConfig } = require("../config");\n+const { spawnSync } = require("child_process");\n+const fs = require("fs");\n+const os = require("os");\n+const path = require("path");\n+\n+const REPO_ROOT = path.join(__dirname, "..");\n+const MAIN_JS = path.join(REPO_ROOT, "main.js");\n \n describe("levenshteinDistance", () => {\n   test("calculates distance between kitten and sitting as 3", () => {\n@@ -50,6 +58,15 @@ describe("findCity", () => {\n     // Let's try "Brl" -> dist 3.\n     expect(() => findCity("Brl")).toThrow(/Unknown city: Brl\\. Did you mean Berlin\\?/);\n   });\n+\n+  test("throws Error listing all tied cities alphabetically for equidistant query", () => {\n+    // "Munlin" is at Levenshtein distance 3 from both "Munich" and "Berlin",\n+    // and distance 7 from "Hamburg" (verified manually), so it ties within\n+    // the suggestion range and should list both cities alphabetically.\n+    expect(() => findCity("Munlin")).toThrow(\n+      "Unknown city: Munlin. Did you mean Berlin or Munich?"\n+    );\n+  });\n });\n \n describe("getWeather", () => {\n@@ -64,4 +81,160 @@ describe("getWeather", () => {\n     expect(result.city).toBe("Berlin");\n     expect(result.corrected).toBe(false);\n   });\n+\n+  test